-- ICT371 Question 3: Library Returns and Overdue Fines (MySQL 8.0)
CREATE DATABASE IF NOT EXISTS ict371_q03_library; USE ict371_q03_library;
CREATE TABLE Books(book_id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL);
CREATE TABLE Loans(loan_id BIGINT AUTO_INCREMENT PRIMARY KEY,book_id INT NOT NULL,borrower_name VARCHAR(120) NOT NULL,borrowed_on DATE NOT NULL,due_on DATE NOT NULL,returned_on DATE NULL,fine_amount DECIMAL(12,2) NOT NULL DEFAULT 0,CONSTRAINT ck_loan_dates CHECK(due_on>=borrowed_on),FOREIGN KEY(book_id) REFERENCES Books(book_id));
CREATE TABLE loan_audit(audit_id BIGINT AUTO_INCREMENT PRIMARY KEY,loan_id BIGINT NOT NULL,old_returned_on DATE NULL,new_returned_on DATE NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(loan_id) REFERENCES Loans(loan_id));
CREATE TABLE overdue_summary(snapshot_date DATE PRIMARY KEY,overdue_count BIGINT NOT NULL,total_fine DECIMAL(14,2) NOT NULL);
INSERT INTO Books(title) VALUES('Database Systems'),('Networks'),('SQL Fundamentals');
INSERT INTO Loans(book_id,borrower_name,borrowed_on,due_on,returned_on,fine_amount) VALUES(1,'Lina',CURRENT_DATE-INTERVAL 15 DAY,CURRENT_DATE-INTERVAL 8 DAY,NULL,0),(2,'Moses',CURRENT_DATE-INTERVAL 12 DAY,CURRENT_DATE-INTERVAL 5 DAY,CURRENT_DATE-INTERVAL 5 DAY,0),(3,'Ruth',CURRENT_DATE-INTERVAL 4 DAY,CURRENT_DATE+INTERVAL 3 DAY,NULL,0),(1,'Peter',CURRENT_DATE-INTERVAL 20 DAY,CURRENT_DATE-INTERVAL 10 DAY,CURRENT_DATE-INTERVAL 7 DAY,6),(2,'Grace',CURRENT_DATE-INTERVAL 3 DAY,CURRENT_DATE+INTERVAL 4 DAY,NULL,0),(3,'John',CURRENT_DATE-INTERVAL 9 DAY,CURRENT_DATE-INTERVAL 2 DAY,NULL,0);
DELIMITER $$
CREATE FUNCTION fn_loan_fine(p_loan_id BIGINT,p_as_of DATE) RETURNS DECIMAL(12,2) DETERMINISTIC READS SQL DATA BEGIN DECLARE v_due DATE; DECLARE v_return DATE; SELECT due_on,returned_on INTO v_due,v_return FROM Loans WHERE loan_id=p_loan_id; IF v_due IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown loan'; END IF; RETURN GREATEST(DATEDIFF(LEAST(COALESCE(v_return,p_as_of),p_as_of),v_due),0)*2.00; END$$
CREATE TRIGGER trg_loan_return_audit AFTER UPDATE ON Loans FOR EACH ROW BEGIN IF NOT (OLD.returned_on <=> NEW.returned_on) THEN INSERT INTO loan_audit(loan_id,old_returned_on,new_returned_on) VALUES(NEW.loan_id,OLD.returned_on,NEW.returned_on); END IF; END$$
CREATE PROCEDURE pr_return_loan(IN p_loan_id BIGINT,IN p_returned_on DATE) BEGIN DECLARE v_borrowed DATE; DECLARE v_return DATE; DECLARE v_fine DECIMAL(12,2); IF p_returned_on IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Return date required'; END IF; SELECT borrowed_on,returned_on INTO v_borrowed,v_return FROM Loans WHERE loan_id=p_loan_id; IF v_borrowed IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown loan'; END IF; IF v_return IS NOT NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Loan already returned'; END IF; IF p_returned_on<v_borrowed THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Return precedes borrowing'; END IF; SET v_fine=GREATEST(DATEDIFF(p_returned_on,(SELECT due_on FROM Loans WHERE loan_id=p_loan_id)),0)*2.00; UPDATE Loans SET returned_on=p_returned_on,fine_amount=v_fine WHERE loan_id=p_loan_id; END$$
CREATE PROCEDURE pr_refresh_overdue(IN p_as_of DATE) BEGIN INSERT INTO overdue_summary(snapshot_date,overdue_count,total_fine) SELECT p_as_of,COUNT(*),COALESCE(SUM(fn_loan_fine(loan_id,p_as_of)),0) FROM Loans WHERE returned_on IS NULL AND due_on<p_as_of ON DUPLICATE KEY UPDATE overdue_count=VALUES(overdue_count),total_fine=VALUES(total_fine); END$$
DELIMITER ;
CREATE VIEW v_overdue_loans AS SELECT b.title,l.borrower_name,l.due_on,fn_loan_fine(l.loan_id,CURRENT_DATE) fine_as_of_today FROM Loans l JOIN Books b ON b.book_id=l.book_id WHERE l.returned_on IS NULL AND l.due_on<CURRENT_DATE;
CREATE INDEX ix_loans_book_return_due ON Loans(book_id,returned_on,due_on);
EXPLAIN SELECT loan_id,borrower_name,due_on FROM Loans WHERE book_id=1 AND returned_on IS NULL;
SET GLOBAL event_scheduler=ON;
CREATE EVENT IF NOT EXISTS ev_refresh_overdue ON SCHEDULE EVERY 1 DAY STARTS (TIMESTAMP(CURRENT_DATE+INTERVAL 1 DAY,'00:10:00')) DO CALL pr_refresh_overdue(CURRENT_DATE);
